package com.xlays.c00lgui.modules.visual;
import net.minecraft.client.Minecraft;import net.minecraft.client.player.LocalPlayer;import net.minecraft.core.BlockPos;import net.minecraft.gizmos.GizmoStyle;import net.minecraft.gizmos.Gizmos;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.Blocks;import java.util.*;
public final class OreESP{
 public enum OreGroup{
  COAL("Coal",Blocks.COAL_ORE,Blocks.COAL_ORE,Blocks.DEEPSLATE_COAL_ORE),IRON("Iron",Blocks.IRON_ORE,Blocks.IRON_ORE,Blocks.DEEPSLATE_IRON_ORE),COPPER("Copper",Blocks.COPPER_ORE,Blocks.COPPER_ORE,Blocks.DEEPSLATE_COPPER_ORE),GOLD("Gold",Blocks.GOLD_ORE,Blocks.GOLD_ORE,Blocks.DEEPSLATE_GOLD_ORE),REDSTONE("Redstone",Blocks.REDSTONE_ORE,Blocks.REDSTONE_ORE,Blocks.DEEPSLATE_REDSTONE_ORE),LAPIS("Lapis",Blocks.LAPIS_ORE,Blocks.LAPIS_ORE,Blocks.DEEPSLATE_LAPIS_ORE),DIAMOND("Diamond",Blocks.DIAMOND_ORE,Blocks.DIAMOND_ORE,Blocks.DEEPSLATE_DIAMOND_ORE),EMERALD("Emerald",Blocks.EMERALD_ORE,Blocks.EMERALD_ORE,Blocks.DEEPSLATE_EMERALD_ORE),ANCIENT_DEBRIS("Ancient Debris",Blocks.ANCIENT_DEBRIS,Blocks.ANCIENT_DEBRIS);
  private final String label;private final Block icon;private final List<Block> blocks;
  OreGroup(String n,Block i,Block... b){label=n;icon=i;blocks=List.of(b);}public String getLabel(){return label;}public Block getIcon(){return icon;}public List<Block> getBlocks(){return blocks;}
 }
 private static boolean enabled=false;private static int radius=12,tickCounter=0;private static final List<BlockPos> ORES=new ArrayList<>();private static final EnumMap<OreGroup,Boolean> FILTERS=new EnumMap<>(OreGroup.class);
 static{for(OreGroup g:OreGroup.values())FILTERS.put(g,true);}private OreESP(){}
 public static boolean isEnabled(){return enabled;}public static void setEnabled(boolean v){enabled=v;if(!v){ORES.clear();tickCounter=0;}}public static void toggle(){setEnabled(!enabled);}
 public static int getRadius(){return radius;}public static void setRadius(int v){radius=Math.max(4,Math.min(32,v));}
 public static boolean isOreEnabled(OreGroup g){return FILTERS.getOrDefault(g,true);}public static void setOreEnabled(OreGroup g,boolean v){FILTERS.put(g,v);ORES.clear();}public static void toggleOre(OreGroup g){setOreEnabled(g,!isOreEnabled(g));}
 private static boolean target(Block b){for(OreGroup g:OreGroup.values())if(isOreEnabled(g)&&g.blocks.contains(b))return true;return false;}
 public static void tick(){if(!enabled){ORES.clear();return;}Minecraft mc=Minecraft.getInstance();LocalPlayer p=mc.player;if(p==null||mc.level==null){ORES.clear();return;}if(++tickCounter<10)return;tickCounter=0;BlockPos c=p.blockPosition();List<BlockPos> found=new ArrayList<>();for(int x=-radius;x<=radius;x++)for(int y=-radius;y<=radius;y++)for(int z=-radius;z<=radius;z++){BlockPos pos=c.offset(x,y,z);if(target(mc.level.getBlockState(pos).getBlock()))found.add(pos.immutable());}ORES.clear();ORES.addAll(found);}
 public static void render(){if(!enabled||ORES.isEmpty())return;Minecraft mc=Minecraft.getInstance();if(mc.level==null||mc.player==null)return;for(BlockPos p:ORES){Block b=mc.level.getBlockState(p).getBlock();Gizmos.cuboid(p,GizmoStyle.stroke(getColor(b),2.0F)).setAlwaysOnTop();}}
 public static int getColor(Block b){if(b==Blocks.DIAMOND_ORE||b==Blocks.DEEPSLATE_DIAMOND_ORE)return 0xFF55FFFF;if(b==Blocks.EMERALD_ORE||b==Blocks.DEEPSLATE_EMERALD_ORE)return 0xFF55FF55;if(b==Blocks.GOLD_ORE||b==Blocks.DEEPSLATE_GOLD_ORE)return 0xFFFFD700;if(b==Blocks.IRON_ORE||b==Blocks.DEEPSLATE_IRON_ORE)return 0xFFFFAA66;if(b==Blocks.COPPER_ORE||b==Blocks.DEEPSLATE_COPPER_ORE)return 0xFFFF8844;if(b==Blocks.REDSTONE_ORE||b==Blocks.DEEPSLATE_REDSTONE_ORE)return 0xFFFF2222;if(b==Blocks.LAPIS_ORE||b==Blocks.DEEPSLATE_LAPIS_ORE)return 0xFF4444FF;if(b==Blocks.COAL_ORE||b==Blocks.DEEPSLATE_COAL_ORE)return 0xFF777777;if(b==Blocks.ANCIENT_DEBRIS)return 0xFFAA55AA;return 0xFFFFFFFF;}
 public static void disable(){setEnabled(false);}
}